  host.innerHTML='<div class="rt-modal"><div class="rt-mbox"><h3>'+esc(slot)+'</h3><p>Name for every '+esc(slot)+' cell today</p><input id="rt-in" type="text" maxlength="24" autocomplete="off" autocapitalize="words" value="'+esc(cur)+'" placeholder="Type name"><div class="rt-chips">'+chips+'</div><div class="rt-mrow"><button class="rt-b" data-a="cancel">Cancel</button>'+(cur?'<button class="rt-b" data-a="remove">Clear</button>':'')+'<button class="rt-b pri" data-a="ok">Save</button></div></div></div>';
